<?php use Hls\Http\View as V; ?><section class="panel"><p>Nomor: <strong><?= V::escape($row['adjustment_ref']) ?></strong></p><p>Cabang: <?= V::escape($row['branch_code']) ?> · Gudang: <?= V::escape($row['warehouse_code']) ?> · Status: <?= V::escape($row['status']) ?></p><p>Alasan: <?= V::escape($row['reason']) ?></p><?php foreach(['submit'=>'Kirim','approve'=>'Setujui','reject'=>'Tolak','cancel'=>'Batalkan','post'=>'Posting'] as $k=>$label): $perm=['submit'=>'inventory.adjustment.submit','approve'=>'inventory.adjustment.approve','reject'=>'inventory.adjustment.reject','cancel'=>'inventory.adjustment.cancel','post'=>'inventory.adjustment.post'][$k]; if($access->can($perm)): ?><form method="post" action="<?= $this->url('/inventory/adjustment-transition') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="transition" value="<?= $k ?>"><button class="button"><?= $label ?></button></form><?php endif; endforeach ?></section><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Qty</th><th>Satuan</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= V::escape($l['item_code'].' - '.$l['item_name']) ?></td><td><?= number_format((float)$l['quantity_change'],3,',','.') ?></td><td><?= V::escape($l['unit_name']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
